INSERT INTO `announcements` (`id`, `title`, `description`, `image_path`, `created_at`) VALUES
(8, 'Iloilo City Government', '\r\nMORE PHOTOS | A total of 370 athletes from 19 countries came together in Iloilo City for the 2nd IPSC Action Air World Shoot, officially opening on July 29, 2025 at Ateneo de Iloilo.\r\nAmong those present were IPSC President Vitaly Kryuchin; PPSA President and IPSC Regional Director for the Philippines Edwin B. Lim; IPSC Regional Director for Guam Philip Benjamin Santos; and Dino Evangelinos, President of the International Range Officers Association (IROA), which is responsible for officiating the match.\r\n📷 S. Bacinillo & R.J. Tarrosa / Iloilo City PIO\r\n#RISETOACTION\r\n#RISEIloiloCity\r\n#USWAGILOILO', '', '2025-07-30 12:03:47');
INSERT INTO `apartments` (`id`, `name`, `image`, `image_detail`, `description`, `location`, `maps_embed`, `maps_link`, `directions_link`, `website`, `hours`, `contact`, `amenities`, `social_media`, `details_link`, `property_type`, `year_built`, `email`, `nearby_places`, `transportation_routes`, `created_at`) VALUES
(1, 'One Madison Place Luxury Residences', 'uploads/One Madison Place Luxury Residences.jpg', 'uploads/img_68ec730d0a3f02.93988568.jpg,uploads/img_68f87f73f3f415.98722366.png', 'Own a luxury condo in Iloilo Business Park by Megaworld Corporation, the Philippines’ #1 residential developer.\r\n\r\nChoose from Firenze Residences, The Pinnacle, Saint Dominique, Saint Honore, The Palladium, Lafayette Park Square, or One Madison Place—all offering prime location, world-class amenities, and high investment potential. \r\n\r\nOMP-LayoutOne Madison Place is the first condominium project of Megaworld in Iloilo City. It is composed of 3 Towers, with the 1st tower declared to be sold out in less than two months.\r\n\r\nThe overall design of One Madison Place is evidently modern. The condominium will have full standard amenities like pools, gym, and playground. It aims for a holistic, safe, and luxurious residential experience.\r\n\r\nTowers 2 and 3 still have available studio, executive, 0ne-bedroom, and two-bedroom units available. Currently, the prices is at their lowest with easy payment terms.', 'Mandurriao, Iloilo City, Iloilo', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d125462.35792210548!2d122.29532506426938!3d10.680479889817684!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee52ffc7ea5a5%3A0xc9048fa99e77c9e0!2sOne%20Madison%20Place%20Luxury%20Residences!5e0!3m2!1sfil!2sph!4v1759904324949!5m2!1sfil!2sph', 'https://maps.app.goo.gl/saT227x58o9eczVbA', 'https://www.google.com/maps/dir//One+Madison+Place+Luxury+Residences,+Mandurriao,+Iloilo+City,+Iloilo/@10.6804799,122.2953251,12z/data=!4m16!1m7!3m6!1s0x33aee52ffc7ea5a5:0xc9048fa99e77c9e0!2sOne+Madison+Place+Luxury+Residences!8m2!3d10.7187171!4d122.5481757!16s%2Fg%2F11dymnp6t3!4m7!1m0!1m5!1m1!1s0x33aee52ffc7ea5a5:0xc9048fa99e77c9e0!2m2!1d122.5481757!2d10.7187171?entry=ttu&g_ep=EgoyMDI1MTAxMi4wIKXMDSoASAFQAw%3D%3D', 'https://iloilocondominiums.com/one-madison-place/', 'Monday - Saturday: 8 AM–5 PM\r\nSunday: Closed', '09475801880 |0928-503-5321', '[]', 'https://www.facebook.com/onemadisonplaceiloilo/', 'apartment1.php', '', '', 'consult@iloilocondominiums.com', '[]', '[{\"type\":\"bus\",\"name\":\"Route 19: BITO-ON TO CITY PROPER VIA LA PAZ\",\"link\":\"bus19.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"Route 19: BITO-ON TO CITY PROPER VIA LA PAZ\",\"link\":\"jeep19.php\",\"description\":\"\"}]', '2025-10-08 07:18:40'),
(2, 'BDS Apartment', 'uploads/BDS Apartment.jpg', 'uploads/img_68ec731d6dc007.96148801.jpg,uploads/img_68f87f7d39f403.39517155.png', 'BDS Apartment in Iloilo City is a long-standing apartment and condo building located in the City Proper district, offering accommodation for both short-term guests and long-term residents.', '140 Delgado St, Iloilo City Proper, Iloilo City, Iloilo', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d125455.26139374329!2d122.40504129726561!3d10.697649900000007!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee55d2c983589%3A0x908de359590321d4!2sBDS%20Apartment!5e0!3m2!1sfil!2sph!4v1759904347464!5m2!1sfil!2sph', 'https://maps.app.goo.gl/K7ntUqtMpQ8GwcE3A', 'https://www.google.com/maps/dir//BDS+Apartment,+140+Delgado+St,+Iloilo+City+Proper,+Iloilo+City,+Iloilo/@10.6976499,122.4050413,12z/data=!4m16!1m7!3m6!1s0x33aee55d2c983589:0x908de359590321d4!2sBDS+Apartment!8m2!3d10.6976499!4d122.5574766!16s%2Fg%2F11g6bfsq7k!4m7!1m0!1m5!1m1!1s0x33aee55d2c983589:0x908de359590321d4!2m2!1d122.557455!2d10.6976675?entry=ttu&g_ep=EgoyMDI1MTAxMi4wIKXMDSoASAFQAw%3D%3D', '', 'Always open', '09171835542', '[]', 'https://www.facebook.com/bds.apartment/', 'apartment2.php', '', '', '', '[]', '[{\"type\":\"bus\",\"name\":\"ROUTE 4: UNGKA TO CITY PROPER VIA DIVERSION FESTIVE WALK LOOP\",\"link\":\"bus4.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 5: FESTIVE WALK TO CITY PROPER VIA B. AQUINO AVE. AND SM CITY\",\"link\":\"bus5.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 7: COMPANIA TO CITY PROPER LOOP\",\"link\":\"bus7.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 9: MOHON TO CITY PROPER LOOP\",\"link\":\"bus9.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 12: MANDURRIAO TO CITY PROPER VIA FESTIVE WALK \\/ B. AQUINO AVE.\",\"link\":\"bus12.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 4: UNGKA TO CITY PROPER VIA DIVERSION FESTIVE WALK LOOP\",\"link\":\"jeep4.php\",\"d