(14, 'St. Clement’s Church (Redemptorists)', 'uploads/st.clements.jpg', 'uploads/img_68e5dbd7c8ae24.14460483.jpg,uploads/img_68f8e61c934465.51904181.png', 'St. Clement\'s Church-Redemptorists (Our Mother of Perpetual Help Parish, La Paz, Iloilo City) is owned and managed by the Redemptorist Missionaries.', 'Saint Clement\'s Compound, 46 Luna St, La Paz, Iloilo City, 5000 Iloilo', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.315955947556!2d122.5651955!3d10.7100952!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee514721aad99%3A0xd557a26a9b3d7056!2sSt.%20Clement&amp;amp;amp;#39;s%20Church%20-%20Redemptorists%20Iloilo!5e0!3m2!1sen!2sph!4v1760455920644!5m2!1sen!2sph', 'https://maps.app.goo.gl/C2z4TuLH5juiLmsC6', '', 'https://www.google.com/maps/dir//St.+Clement\'s+Church+-+Redemptorists+Iloilo,+Saint+Clement\'s+Compound,+46+Luna+St,+La+Paz,+Iloilo+City,+5000+Iloilo/@10.7100952,122.5651955,17z/data=!4m16!1m7!3m6!1s0x33aee514721aad99:0xd557a26a9b3d7056!2sSt.+Clement\'s+Church+-+Redemptorists+Iloilo!8m2!3d10.7100952!4d122.5651955!16s%2Fg%2F1hc10qy_8!4m7!1m0!1m5!1m1!1s0x33aee514721aad99:0xd557a26a9b3d7056!2m2!1d122.5652427!2d10.710115?entry=ttu&g_ep=EgoyMDI1MTAxMi4wIKXMDSoASAFQAw%3D%3D', '', '(033) 323 1568', '[]', '', 'church14.php', NULL, '2025-09-28 22:44:52', 'redemptorist.iloilo@gmail.com', '[{\"type\":\"jeepney\",\"name\":\"ROUTE 3: UNGKA TO CITY PROPER VIA CPU LOOP\",\"link\":\"jeep3.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 10: BUNTATALA \\/ TAGBAK TERMINAL TO CITY PROPER LOOP\",\"link\":\"jeep10.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 3: UNGKA TO CITY PROPER VIA CPU LOOP\",\"link\":\"bus3.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 10: BUNTATALA \\/ TAGBAK TERMINAL TO CITY PROPER LOOP\",\"link\":\"bus10.php\",\"description\":\"\"}]'),
(15, 'Victory Christian Fellowship', 'uploads/victory.jpg', 'uploads/img_68e5e3cc000d51.79988946.jpg,uploads/img_68f8e6274cd0c8.25525332.png', 'Victory Iloilo, also known as Victory Christian Fellowship of Iloilo, is a Christian church located in Mandurriao, Iloilo City, Philippines. It is part of the national Victory network, a multi-site evangelical church affiliated with Every Nation Churches, with a mission to honor God and make disciples.', 'Victory Center, Paseo de Arcangeles, Senator Benigno S. Aquino Jr. Ave, Mandurriao, Iloilo City, Iloilo', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.2425806293772!2d122.54979897504097!3d10.715763689429343!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee53b1cff973b%3A0xa63fbf8f52b4304d!2sVictory%20Iloilo%20-%20Mandurriao!5e0!3m2!1sfil!2sph!4v1759037749236!5m2!1sfil!2sph', 'https://maps.app.goo.gl/go6fRYCKqfBxoEBZ8', '', 'https://www.google.com/maps/dir//Victory+Iloilo+-+Mandurriao,+Victory+Center,+Paseo+de+Arcangeles,+Senator+Benigno+S.+Aquino+Jr.+Ave,+Mandurriao,+Iloilo+City,+Iloilo/@10.7157637,122.5523739,17z/data=!4m16!1m7!3m6!1s0x33aee53b1cff973b:0xa63fbf8f52b4304d!2sVictory+Iloilo+-+Mandurriao!8m2!3d10.7157637!4d122.5523739!16s%2Fg%2F1hc0s952g!4m7!1m0!1m5!1m1!1s0x33aee53b1cff973b:0xa63fbf8f52b4304d!2m2!1d122.5523739!2d10.7157637?entry=ttu&g_ep=EgoyMDI1MTAxMi4wIKXMDSoASAFQAw%3D%3D', 'Sunday: 9:00 AM - 6:00 PM', '(033) 330 3032', '[]', 'https://www.facebook.com/victoryiloilocity/', 'church15.php', NULL, '2025-10-06 12:42:46', 'iloilo@victory.org.ph', '[{\"type\":\"jeepney\",\"name\":\"ROUTE 4: UNGKA TO CITY PROPER VIA DIVERSION FESTIVE WALK LOOP\",\"link\":\"jeep4.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 5: FESTIVE WALK TO CITY PROPER VIA B. AQUINO AVE. AND SM CITY\",\"link\":\"jeep5.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 6: LANIT TO SM CITY VIA INFANTE\",\"link\":\"jeep6.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 12: M