INSERT INTO `districts` (`id`, `name`, `image`, `image_detail`, `feast`, `tribe`, `hotlines`, `location`, `description`, `history`, `fun_fact`, `source`, `population`, `area`, `barangays`, `zip_code`, `established`, `contact`, `email`, `hours`, `fee`, `parking`, `bike_parking`, `transportation_options`, `nearby_places`, `social_media`, `website`, `maps_link`, `maps_embed`, `directions_link`, `details_link`) VALUES
(1, 'District of City Proper', 'uploads/cityproper.png', 'uploads/img_68a5e17a861889.85514635.png', 'January 25\r\n', ' Dinagyang Festival', ' 0333370400\r\n                            ', 'Iloilo City Proper, Iloilo City, Iloilo', 'Iloilo City Proper, also known as Downtown Iloilo or simply Iloilo among locals, is an administrative district in Iloilo City, Philippines, located on the southeastern coast of the island of Panay in the Western Visayas region.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'https://maps.app.goo.gl/zLBq3NtEX8gcCvcU7', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15681.969784600002!2d122.55916144467274!3d10.69644858115818!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee56f8b040969%3A0xdadd3562e0747fe6!2sIloilo%20City%20Proper%2C%20Iloilo%20City%2C%20Il', 'https://maps.app.goo.gl/zLBq3NtEX8gcCvcU7', 'district1.php'),
(2, 'District of Arevalo', 'uploads/arevalo.png', 'uploads/img_68a5e1fa5919f1.09166493.png', 'January 19', ' Paraw Regatta Festival\r\n', '                                                    ', 'Villa Arevalo District, Iloilo City, Iloilo', 'Villa de Arevalo, commonly known as simply Villa or Arevalo, is a district in Iloilo City, Philippines. It is the westernmost district of Iloilo City and shares its border with Oton to the west, in the province of Iloilo, on the island of Panay in the Wes', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'https://maps.app.goo.gl/fey21dEKGh3MrWUx7', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15682.447847262036!2d122.50301944467053!3d10.687197581297367!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aef073a2604edf%3A0x334a25b6ae32cc83!2sVilla%20Arevalo%20District%2C%20Iloilo%20City%2C', 'https://maps.app.goo.gl/fey21dEKGh3MrWUx7', 'district2.php'),
(3, 'District of Molo', 'uploads/molo.png', 'uploads/img_68a5e2e14f30e7.03626100.png', 'July 26\r\n', 'Tribu Parianon', '                                                    ', 'Molo, Iloilo City, Iloilo', 'Molo is a historic district in Iloilo City, Philippines, known for its colonial architecture and cultural heritage. It is famous for the Molo Church, often called the \"Athens of the Philippines\" due to its intellectual history. ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'https://maps.app.goo.gl/q5qyiCAWqixfLw238', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15682.290962621979!2d122.53096789467124!3d10.690234331251684!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee5558cbbcaef%3A0x717d2599ff94c296!2sMolo%2C%20Iloilo%20City%2C%20Iloilo!5e0!3m2!1sen', 'https://maps.app.goo.gl/q5qyiCAWqixfLw238', 'district3.php'),
(4, 'District of Lapaz', 'uploads/lapaz.png', 'uploads/img_68a5e3d2e047f9.07271941.png', 'District of Lapaz\r\n', 'Tribu Paghidaet\r\n', '                                                    ', 'La Paz, Iloilo City, Iloilo', 'La Paz is a district in Iloilo City, Philippines, known for its bustling public market and as the birthplace of La Paz batchoy, a famous noodle dish. It is a lively area with a mix of residential, commercial, and educational establishments .Lapuz is a district in Iloilo City, Philippines. It is the smallest district by geographical area as well as the least populous district, with 31,603 people in the 2024 census.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'https://maps.app.goo.gl/QYwzybXEAHzesikb8', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d22176.026927719777!2d122.5603383072587!3d10.718684681773174!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee508bcc075c3%3A0x7f47e3a00fc75b26!2sLa%20Paz%2C%20Iloilo%20City%2C%20Iloilo!5e0!3m2!1', 'https://maps.app.goo.gl/QYwzybXEAHzesikb8', 'district4.php'),
(5, 'District of Jaro', 'uploads/jaro.png', 'uploads/img_68a5e4af9639e7.63702858.png', 'February 2\r\n', 'Tribu Salognon\r\n', '                                                    ', 'Jaro, Iloilo City, Iloilo', 'Jaro is a district in Iloilo City, Philippines. It is the largest district in terms of both geographical area and population, with 130,700 people according to the 2020 census.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'https://maps.app.goo.gl/zjChcxpS9kVKpJDp7', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d44347.60132708217!2d122.5443258776444!3d10.749029281796835!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee492f062eda9%3A0x9ba8a0438d5e2c6b!2sJaro%2C%20Iloilo%20City%2C%20Iloilo!5e0!3m2!1sen!2', 'https://maps.app.goo.gl/zjChcxpS9kVKpJDp7', 'district5.php'),
(6, 'District of Mandurriao', 'uploads/mandurriao.png', 'uploads/img_68a5e51d853318.74506768.png', ' November 26\r\n', 'Tribu Pag-asa Kang Manduryaw \r\n', '                                                    ', 'Mandurriao, Iloilo City, Iloilo', 'Mandurriao is a district in Iloilo City, Philippines, known for its urban development and the Iloilo Business Park. It is a growing commercial and residential area, contributing significantly to the city\'s economy. Mandurriao is a district in Iloilo City, Philippines. It is the second-largest district by geographical area as well as the third-most populous district, with 66,464 people in the 2024 census. Mandurriao is one of the major business districts of Iloilo City, along with Iloilo City Proper.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'https://maps.app.goo.gl/1fafnmRrqEVjm6PX8', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d31361.87658947845!2d122.51474324374163!3d10.716382073423755!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aefaccec7735ad%3A0xa1e502c24d30b4ef!2sMandurriao%2C%20Iloilo%20City%2C%20Iloilo!5e0!3m2', 'https://maps.app.goo.gl/1fafnmRrqEVjm6PX8', 'district6.php'),
(7, 'District of lapuz', 'uploads/lapuz.png', 'uploads/img_68a5e575ccd6a2.32664626.png', ' August 6\r\n', 'Tribu Ilonganon\r\n', '                                                    ', 'Lapuz, Iloilo City, Iloilo', 'Lapuz is a district in Iloilo City, Philippines, known for its residential and commercial areas. It is home to the bustling Lapuz Market and serves as a key part of the city\'s growing economy. The district is also known for its proximity to the Iloilo River. Lapuz is a district in Iloilo City, Philippines. It is the smallest district by geographical area as well as the least populous district, with 31,603 people in the 2024 census.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'https://maps.app.goo.gl/97etv5d4dXiM71M78', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d31363.38068628833!2d122.58534692897862!3d10.701852397938177!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee59fce63c55d%3A0x8b62634de988c2a7!2sLapuz%2C%20Iloilo%20City%2C%20Iloilo!5e0!3m2!1sen', 'https://maps.app.goo.gl/97etv5d4dXiM71M78', 'district7.php');
