(1, 'Molo 1 Elementary School', 'uploads/molo1.jpg', 'uploads/img_689048e5c93b99.70593655.jpg,uploads/img_68f865667d48d8.58056651.png', 'San Pedro Molo Iloilo City', 'Public school in Molo, Iloilo City, offering education from Kindergarten to Grade 6. It focuses on academic excellence and holistic development for its students.\r\n', 'https://web.facebook.com/Molo1ES/?utm_source=chatgpt.com&_rdc=1&_rdr#', 'https://maps.app.goo.gl/PdGQJUtyn8ZBnoTP9', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.46457337565!2d122.54551652451623!3d10.698604910625399!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee550039863e3%3A0x52368af07eaaf84e!2sMolo%20I%20Elementary%20School%2C%20San%20Pedro%20', 'https://www.google.com/maps/dir//Molo+I+Elementary+School,+San+Pedro+St,+Molo,+Iloilo+City,+Iloilo/@10.6985996,122.5480915,17z/data=!4m8!4m7!1m0!1m5!1m1!1s0x33aee550039863e3:0x52368af07eaaf84e!2m2!1d122.5481013!2d10.6985637?entry=ttu&g_ep=EgoyMDI1MDczMC4w', '', '', '', 'elementary1.php', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '[{\"type\":\"jeepney\",\"name\":\"Route 15: MOLO TO CITY PROPER VIA BULAURTE\",\"link\":\"jeep15.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"Route 17: VILLA BAYBAY TO CITY PROPER VIA BONIFACIO\",\"link\":\"jeep17.php\",\"description\":\"\"}]'),
(2, 'Baluarte elementary School', 'uploads/baluarte.jpg', 'uploads/img_68904926565da9.25295427.jpg,uploads/img_68f8656f6656b5.35578094.png', 'Lopez Jaena St, Molo, Iloilo City, Iloilo', 'A public school known for engaging students from Kindergarten to Grade 6 in activities that enhance literacy, creativity, and overall development.\r\n\r\n', 'https://web.facebook.com/p/Baluarte-Elementary-School-Iloilo-City-100060519931457/?_rdc=1&_rdr#', 'https://maps.app.goo.gl/DT627j8La9q7zhrL8', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.5420759918024!2d122.54596827480363!3d10.692607989451108!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee5576739f401%3A0x48789e30a6228078!2sBALUARTE%20ELEMENTARY%20SCHOOL!5e0!3m2!1sen!2sph', 'https://www.google.com/maps?um=1&ie=UTF-8&fb=1&gl=ph&sa=X&geocode=KQH0OWdX5a4zMXiAIqYwnnhI&daddr=45+Lopez+Jaena+St,+Molo,+Iloilo+City,+Iloilo', '', '', '', 'elementary2.php', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '[{\"type\":\"jeepney\",\"name\":\"Route 15: MOLO TO CITY PROPER VIA BULAURTE\",\"link\":\"jeep15.php\",\"description\":\"\"}]'),
(3, 'Rizal elementary School', 'uploads/rizal.jpg', 'uploads/img_68904a18794f53.05121241.jpg,uploads/img_68f86576b5a074.20520231.png', ' Iloilo City Proper, Iloilo City, Iloilo', 'Established in the early 1900s, this public school has a long-standing reputation for providing quality education to the community.\r\n', 'https://web.facebook.com/RizalElementarySchoolIloiloCity/?_rdc=1&_rdr#', 'https://maps.app.goo.gl/YXAVgYj6ud4Axhsr6', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d250815.13134776708!2d122.37756304017223!3d10.812350221089956!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee573c9960f3b%3A0x99e3e8f3a57421ee!2sRizal%20Elementary%20School!5e0!3m2!1sen!2sph!4v', 'https://www.google.com/maps/dir//PH2F%2BMQM+Rizal+Elementary+Sch,+Rizal+St,+Lapuz,+Iloilo+City,+Iloilo/@10.8123502,122.377563,11z/data=!4m17!1m8!3m7!1s0x33aee573c9960f3b:0x99e3e8f3a57421ee!2sRizal+Elementary+School!8m2!3d10.7017228!4d122.574432!15sChdSaXp', '', '', '', 'elementary3.php', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '[{\"type\":\"jeepney\",\"name\":\"Route 15: MOLO TO CITY PROPER VIA BULAURTE\",\"link\":\"jeep15.php\",\"description\":\"\"}]'),
