INSERT INTO `ferries` (`id`, `name`, `image`, `description`, `type`, `origin`, `destination`, `stopovers`, `departure_time`, `arrival_time`, `frequency`, `fare_rates`, `booking_info`, `amenities`, `requirements`, `location`, `google_map`, `phone`, `email`, `website`, `gallery_images`, `policies`, `rating`, `reviews`, `nearby`, `created_at`, `updated_at`, `details_link`, `operator`, `capacity`, `travel_time`, `safety_rating`, `pet_policy`, `social_media`, `transportation_routes`) VALUES
(1, '2GO Travel', 'uploads/2GO.jpg', '2GO Travel believes that the best way to experience the Philippines is by sea. With over 148 years of experience, we continue to redefine and elevate the sea travel, and provide memorable experiences for all.\r\n\r\nYour vacation begins the moment you step aboard 2GO Travel ships. Enjoy cruise-like comfort with clean, air-conditioned accommodations and a variety of amenities, including shops, dining options, and entertainment. Indulge in shopping at Watsons, ShipMart, Miniso, Kultura, and savor treats from Goldilocks and Brownies Unlimited. Delight in dining at Cafe 2GO, Island Fiesta Restaurant, and the exclusive Horizon Cafe for first-class passengers.\r\n\r\nRelax and unwind with on-board entertainment, live music, sing-along challenges, a video arcade, KTV rooms, and a spa and salon. Take in breathtaking views from the Sun Deck, perfect for light exercise and soaking up the serene sea atmosphere.\r\n\r\nChoose from a range of accommodations to fit any budget, from dormitory-style rooms to luxurious suites with private bathrooms and cable TV. Our top-tier Suite Rooms offer the ultimate in comfort and elegance.\r\n\r\nSafety and enjoyment are our priorities, with 24/7 front desk services, onboard security, and medical staff available to assist you.\r\n\r\nAs a part of SM Investments and with over 148 years in the travel and shipping industry, we connect you to 18 ports across Luzon, Visayas, and Mindanao through our extensive network of over 2,000 outlets nationwide. With us, you\'re always #Ready2GO, connecting you to the places and people you love.', 'M.V 2GO Masagana , M.V 2GO Maligaya, M.V 2GO Masik', '', '', '', '', '', '', '', '', '', '', '', '', '(+63 2) 8528.7000', 'travel@2go.com.ph', 'https://travel.2go.com.ph/', 'uploads/gallery/img_68885fc68a5480.72954434.jpg', '', 0.0, '', '[]', '2025-07-17 10:15:40', '2026-02-27 15:16:32', 'ferry1.php', '', '', '', '', '', '', '[{\"type\":\"jeepney\",\"name\":\"ROUTE 1: BO. OBRERO, LAPUZ TO CITY PROPER LOOP\",\"link\":\"jeep1.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 3: UNGKA TO CITY PROPER VIA CPU LOOP\",\"link\":\"jeep3.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 8: PAROLA TO SM CITY VIA INFANTE LOOP\",\"link\":\"jeep8.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 9: MOHON TO CITY PROPER LOOP\",\"link\":\"jeep9.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 1: BO. OBRERO, LAPUZ TO CITY PROPER LOOP\",\"link\":\"bus1.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 3: UNGKA TO CITY PROPER VIA CPU LOOP\",\"link\":\"bus3.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 8: PAROLA TO SM CITY VIA INFANTE LOOP\",\"link\":\"bus8.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 9: MOHON TO CITY PROPER LOOP\",\"link\":\"jeep9.php\",\"description\":\"\"}]'),
(2, 'Trans-Asia Shipping Lines Iloilo ', 'uploads/Trans-Asia.jpg', 'Our strategy is to build operations into market leaders in every route we ply, each with the support of our extensive knowledge of the Vis-Min area and our long standing relationship with our customers.', '', '', '', '', '', '', '', '', '', '', '', 'Fort Arrastre Pier, PPA Terminal Building, 5000 Fort San Pedro Dr, Iloilo City Proper, Iloilo City, Iloilo', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.568426608151!2d122.57832393488768!3d10.690568299999997!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee5820827ffe9%3A0x806894dfd9819ae7!2sTrans-Asia%20SHIPPING%2C%20LINES%20INC.!5e0!3m2!1', ' (033) 335 8499', 'bvshippingiloilo@outlook.com', 'https://transasiashipping.com/', 'uploads/gallery/img_697f3b5f6ed7a4.70162887.jpg', '', 0.0, '', '[]', '2026-02-01 11:39:11', '2026-02-27 15:20:30', 'ferry2.php', '', '', '', '', '', 'https://www.facebook.com/TransAsiaShippingLinesIloilo', '[{\"type\":\"jeepney\",\"name\":\"ROUTE 1: BO. OBRERO, LAPUZ TO CITY PROPER LOOP\",\"link\":\"jeep1.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"Route 18: TAGBAK TO CITY PROPER VIA COASTAL\",\"link\":\"jeep18.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 1: BO. OBRERO, LAPUZ TO CITY PROPER LOOP\",\"link\":\"bus1.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"Route 18: TAGBAK TO CITY PROPER VIA COASTAL\",\"link\":\"bus18.php\",\"description\":\"\"}]'),
