INSERT INTO `home_stores` (`id`, `name`, `image`, `image_detail`, `description`, `location`, `maps_embed`, `maps_link`, `website`, `directions_link`, `hours`, `contact`, `nearby_places`, `social_media`, `details_link`, `product_categories`, `services`, `branches`, `email`, `created_at`, `transportation_routes`) VALUES
(1, 'OUR HOME', 'uploads/ourhome.jpg', 'uploads/img_68f229f5910e59.03086535.jpg,uploads/img_68f8fa45e617a6.35234917.png', 'Our Home Iloilo is a contemporary furniture and home décor store. It showcases furniture pieces and decorative items designed to match varied styles and personalities of homemakers—modern, classic, minimalist, etc. They offer both showroom browsing and likely delivery services. Whether you’re looking to furnish a whole room or add accent pieces, Our Home provides a wide selection for home improvement and styling.', 'formerly Jaro West, Basement Level, SM City Mandurriao, Benigno Aqino Ave, Diversion Rd, Iloilo City, 5000 Iloilo', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d31361.36707824575!2d122.52257014374642!3d10.721299573127917!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee53a3402e1e1%3A0x3f53c6122a389558!2sOUR%20HOME!5e0!3m2!1sfil!2sph!4v1760329718818!5m2!1sfil!2sph', 'https://maps.app.goo.gl/2M99aVSArmPBbYRB9', 'https://ourhome.ph/', 'https://www.google.com/maps/dir//OUR+HOME,+formerly+Jaro+West,+Basement+Level,+SM+City+Mandurriao,+Benigno+Aqino+Ave,+Diversion+Rd,+Iloilo+City,+5000+Iloilo/@10.7212996,122.5225701,14z/data=!4m16!1m7!3m6!1s0x33aee53a3402e1e1:0x3f53c6122a389558!2sOUR+HOME!8m2!3d10.7134923!4d122.5504175!16s%2Fg%2F11bzvzs3qh!4m7!1m0!1m5!1m1!1s0x33aee53a3402e1e1:0x3f53c6122a389558!2m2!1d122.5504175!2d10.7134923?entry=ttu&g_ep=EgoyMDI1MTAxNC4wIKXMDSoASAFQAw%3D%3D', 'Open Monday - Sunday: 10:00 AM - 7:00 PM', '(033) 320 7381 | OH.CUSTOMERCARE@smretail.com', '[]', '', 'home_store1.php', '', '', '', '', '2025-10-13 13:19:34', '[{\"type\":\"jeepney\",\"name\":\"ROUTE 4: UNGKA TO CITY PROPER VIA DIVERSION FESTIVE WALK LOOP\",\"link\":\"jeep4.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 5: FESTIVE WALK TO CITY PROPER VIA B. AQUINO AVE. AND SM CITY\",\"link\":\"jeep5.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 6: LANIT TO SM CITY VIA INFANTE\",\"link\":\"jeep6.php\",\"des