(20, 'RUSI', 'uploads/RUSI.jpg', 'uploads/img_68e6250315abf6.53697515.jpg,uploads/img_68f8cc387a7885.51460196.png', 'RUSI (Ramas-Uypitching Sons, Inc.) is a well-known motorcycle brand in the Philippines, offering a range of affordable and reliable motorcycles.', 'QH8J+M7X, Jaro, Iloilo City, Iloilo', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15678.3246257619!2d122.5616754871582!3d10.766727800000009!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee37f0e7381b5%3A0x79b1ee8d6c46afeb!2sRUSI!5e0!3m2!1sfil!2sph!4v1758775616428!5m2!1sfil!2sph', 'https://maps.app.goo.gl/TV7Y6F7KxJqfT5Z2A', 'https://rusimotors.ruscomotorsgroup.net/', 'https://www.google.com/maps/dir//QH8J%2BM7X+RUSI,+Jaro,+Iloilo+City,+Iloilo/@10.7667278,122.5616755,15z/data=!4m16!1m7!3m6!1s0x33aee37f0e7381b5:0x79b1ee8d6c46afeb!2sRUSI!8m2!3d10.7667278!4d122.5807299!16s%2Fg%2F11c5303cw4!4m7!1m0!1m5!1m1!1s0x33aee37f0e7381b5:0x79b1ee8d6c46afeb!2m2!1d122.5807973!2d10.7666869?entry=ttu&g_ep=EgoyMDI1MTAxNC4wIKXMDSoASAFQAw%3D%3D', '', '0998 594 1372', '[]', 'https://www.facebook.com/rusi.jaro', 'motorcycle_shop20.php', '', '', '2025-10-06 12:27:29', '', '', '[{\"type\":\"jeepney\",\"name\":\"ROUTE 3: UNGKA TO CITY PROPER VIA CPU LOOP\",\"link\":\"jeep3.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 10: BUNTATALA \\/ TAGBAK TERMINAL TO CITY PROPER LOOP\",\"link\":\"jeep10.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 3: UNGKA TO CITY PROPER VIA CPU LOOP\",\"link\":\"bus3.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 10: BUNTATALA \\/ TAGBAK TERMINAL TO CITY PROPER LOOP\",\"link\":\"bus10.php\",\"description\":\"\"}]'),
