INSERT INTO `new_tourist_spots` (`id`, `name`, `description`, `history`, `image`, `image_detail`, `features`, `activities`, `location`, `maps_link`, `maps_embed`, `operating_hours`, `entrance_fee`, `best_time_to_visit`, `nearby_places`, `travel_tips`, `website`, `date_added`, `details_link`, `transportation_routes`) VALUES
(1, 'The Iloilo Esplanade ', 'The Evening Invites\r\nA 9-kilometer-long linear park along the Iloilo River is afavorite spot for Ilonggo joggers. It received the \"Haligi ng Dangal Award\" from the National Commission for Culture and the Arts for Landscape Architecture.', '', 'uploads/esplanada.jpeg', 'uploads/img_689b56745a48c5.21799235.jpeg', '', '', 'PH33+287, Iloilo Riverside Blvd, Mandurriao, Iloilo City, Iloilo', 'https://maps.app.goo.gl/DzbYFU2myPxyhYy3A', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.4136492149373!2d122.54841627768381!3d10.702543462218065!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee54410a5f077%3A0xf4945903e915cba9!2sIloilo%20River%20Esplanade%201!5e0!3m2!1sen!2sph', '', '', '', '', '', '', '2025-08-12 14:57:56', 'new_tourist_spot1.php', '[]'),
(2, 'Sunset Boulevard ', '|', '', 'uploads/sunset boulevard.jpg', 'uploads/img_689b57e78c1689.67798676.jpg', '', '', 'Tabucan, Mandurriao, Iloilo City', 'https://maps.app.goo.gl/z7Mc56vJkfEQyySH7', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1960.237956831362!2d122.52222001460508!3d10.697727640566336!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aefa9edbecd61f%3A0xb3aefcf854f4c7fe!2sIloilo%20Sunset%20Blvd%2C%20Iloilo!5e0!3m2!1sen!2', '', '', '', '', '', '', '2025-08-12 15:02:57', 'new_tourist_spot2.php', '[]'),
(3, 'Iloilo Business Park', 'The 72-hectare master planned mixed-use development community capativated with vissionary lifestyle of a strong collaboration for city\'s development. Megaworld\'s Iloilo Business Park is all about business and leisure in Iloilo City indeed a spirited township full of exciting posibilities. A very accessible township where banks are available, a huge and modern mall, more choices for restaurants and accommodations establishments.', NULL, 'uploads/iloilo Business Park.jpg', 'uploads/iloilo Business Park.jpg', '', '', 'Iloilo Business Park, Enterprise Rd, Mandurriao, Iloilo City, 5000 Iloilo', 'https://maps.app.goo.gl/B7gxo1FK8c6Wc4uh8', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.271712760034!2d122.54284677504104!3d10.713513489431474!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee536d08f1cdb%3A0x67f157c0498f65d5!2sIloilo%20Business%20Park!5e0!3m2!1sen!2sph!4v1760', '', '', '', '', '', 'https://megaworldiloilo.com/', '2025-10-20 11:46:20', 'new_tourist_spot3.php', '[]');
