INSERT INTO `printing_services` (`id`, `name`, `image`, `image_detail`, `description`, `location`, `maps_embed`, `maps_link`, `directions_link`, `website`, `hours`, `contact`, `nearby_places`, `social_media`, `details_link`, `services_offered`, `email`, `created_at`, `transportation_routes`) VALUES
(1, 'FISHERMAN PRINT SERVICES', 'uploads/FISHERMAN PRINT SERVICES.jpg', 'uploads/img_68ecdc645f51b7.69479485.jpg,uploads/img_68f88e4347d157.23937574.png', 'Fisherman Print Services Iloilo is a local print shop in Iloilo that offers a range of printing and signage services. Whether you need banners, tarpaulins, posters, business cards, stickers, or other customized printed materials, they aim to deliver quality outputs tailored to client needs. Their name suggests a focus on visual “casting” of designs—much like a fisherman casts nets—delivering your brand or message into public view.\r\nThey cater to both individual and business clients, and may also offer finishing services (lamination, cutting) depending on your design requirements. Their strengths likely lie in fast turnaround, personalized service, and familiarity with Iloilo’s local business environment.', 'ZONE III, Villa Arevalo District, Iloilo City, Iloilo', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.679268430529!2d122.49426807504061!3d10.681984289461129!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aef1882ae157e3%3A0x5127f51da8a94d06!2sFISHERMAN%20PRINT%20SERVICES!5e0!3m2!1sfil!2sph!4v1759744885624!5m2!1sfil!2sph', 'https://maps.app.goo.gl/ja4wjY562vnxCPTb7', 'https://www.google.com/maps/dir//ZONE+III,+FISHERMAN+PRINT+SERVICES,+Villa+Arevalo+District,+Iloilo+City,+Iloilo/@10.6819843,122.496843,17z/data=!4m16!1m7!3m6!1s0x33aef1882ae157e3:0x5127f51da8a94d06!2sFISHERMAN+PRINT+SERVICES!8m2!3d10.6819843!4d122.496843!16s%2Fg%2F11j8qqjmhq!4m7!1m0!1m5!1m1!1s0x33aef1882ae157e3:0x5127f51da8a94d06!2m2!1d122.496843!2d10.6819843?entry=ttu&g_ep=EgoyMDI1MTAxMi4wIKXMDSoASAFQAw%3D%3D', '', 'Monday, 8 AM–5 PM\r\nTuesday, 8 AM–5 PM\r\nWednesday, 8 AM–5 PM\r\nThursday, 8 AM–5 PM\r\nFriday, 8 AM–5 PM\r\nSaturday, Closed\r\nSunday, Closed', '0985 060 7380 | (033) 323 1753 |  Fishermanprinting@yahoo.com', '[]', 'https://www.facebook.com/p/Fisherman-Printing-Press-100063952755510/', 'printing_services1.php', '[]', '', '2025-10-07 07:22:49', '[{\"type\":\"jeepney\",\"name\":\"ROUTE 2: VILLA PLAZA TO CITY PROPER VIA CALUMPANG\",\"link\":\"jeep2.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 9: MOHON TO CITY PROPER LOOP\",\"link\":\"jeep9.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"Route 17: VILLA BAYBAY TO CITY PROPER VIA BONIFACIO\",\"link\":\"jeep17.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 2: VILLA PLAZA TO CITY PROPER VIA CALUMPANG\",\"link\":\"bus2.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 9: MOHON TO CITY PROPER LOOP\",\"link\":\"bus9.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"Route 17: VILLA BAYBAY TO CITY PROPER VIA BONIFACIO\",\"link\":\"bus17.php\",\"description\":\"\"}]'),
(2, 'PANAY BULLETIN', 'uploads/PANAY BULLETIN.jpg', 'uploads/img_68ecdc70dc92f2.42668135.jpg,uploads/img_68f88e4d714931.99869024.png', 'Panay News, Inc. (often referred to as Panay Bulletin) is a regional newspaper and media publisher based in Pavia, Iloilo. It operates as a news outlet and also handles printing, distribution, and advertisement services. The publication provides local and regional news coverage across Iloilo and the Panay area, along with features, public notices, and advertising. As a media institution rooted in its community, it serves both individual readers and businesses seeking to reach a local audience.', 'Brgy. Boulevard Zone 5 Basketball Court, Molo, Iloilo City, Iloilo', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3920.600860659363!2d122.54516757504058!3d10.688057189455403!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aeeff7e5555555%3A0x2d91587f03904613!2sPANAY%20BULLETIN!5e0!3m2!1sfil!2sph!4v1759744924873!5m2!1sfil!2sph', 'https://maps.app.goo.gl/qTyaULYULrks67NF7', 'https://www.google.com/maps/dir//PANAY+BULLETIN,+Brgy.+Boulevard+Zone+5+Basketball+Court,+Molo,+Iloilo+City,+Iloilo/@10.6880572,122.5477425,17z/data=!4m16!1m7!3m6!1s0x33aeeff7e5555555:0x2d91587f03904613!2sPANAY+BULLETIN!8m2!3d10.6880572!4d122.5477425!16s%2Fg%2F11b_0dzz1h!4m7!1m0!1m5!1m1!1s0x33aeeff7e5555555:0x2d91587f03904613!2m2!1d122.5477491!2d10.6880634?entry=ttu&g_ep=EgoyMDI1MTAxMi4wIKXMDSoASAFQAw%3D%3D', '', 'Open Monday - Saturday:  8:30 AM – 5:30 PM', '(033) 396-62  (033) 501-0387  |  0907 3122400 | 09563414867', '[]', 'https://www.facebook.com/panay.bulletin/', 'printing_services2.php', '[]', '', '2025-10-07 07:26:14', '[{\"type\":\"jeepney\",\"name\":\"ROUTE 1: BO. OBRERO, LAPUZ TO CITY PROPER LOOP\",\"link\":\"jeep1.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 3: UNGKA TO CITY PROPER VIA CPU LOOP\",\"link\":\"jeep3.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 9: MOHON TO CITY PROPER LOOP\",\"link\":\"jee