(17, 'Faith Veterinary Clinic', 'uploads/Faith Veterinary Clinic.jpg', 'uploads/68ef18d61a2b5_Faith Veterinary Clinic.jpg,uploads/68f64f7c7b400_Faith Veterinary Clinic.png', 'Faith Veterinary Clinic offers a range of services including consultation, vaccination, deworming, pet salon grooming, and pet boarding to ensure the health and care of your pets.', 'Unit 5, Highway , Star 2 Building, Zone IV R4, Jaro, Iloilo City, Iloilo', 'https://maps.app.goo.gl/mqZmk6pp851ketfV9', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15678.263292846392!2d122.57159214867049!3d10.7679064300838!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x33aee3005e4408bf%3A0x5314145fefa7d3ff!2sFaith%20Veterinary%20Clinic!5e0!3m2!1sen!2sph!4v1759749394577!5m2!1sen!2sph', '', 'Monday 8 AM–8 PM\r\nTuesday 8 AM–8 PM\r\nWednesday 8 AM–8 PM\r\nThursday 8 AM–8 PM\r\nFriday 8 AM–8 PM\r\nSaturday 8 AM–8 PM\r\nSunday 8 AM–8 PM', '09692047491', '', '', '', '', '', '[]', 'https://www.facebook.com/p/Faith-Veterinary-Clinic-61557875039384/', 'https://www.google.com/maps/dir//Unit+5,+Faith+Veterinary+Clinic,+Highway+,+Star+2+Building,+Zone+IV+R4,+Jaro,+Iloilo+City,+Iloilo/@10.7679069,122.2298135,11z/data=!4m8!4m7!1m0!1m5!1m1!1s0x33aee3005e4408bf:0x5314145fefa7d3ff!2m2!1d122.581895!2d10.7679048?entry=ttu&g_ep=EgoyMDI1MDkxMC4wIKXMDSoASAFQAw%3D%3D', 'veterinary17.php', '', '', '', '', '', '', '', '[{\"type\":\"jeepney\",\"name\":\"ROUTE 10: BUNTATALA \\/ TAGBAK TERMINAL TO CITY PROPER LOOP\",\"link\":\"jeep10.php\",\"description\":\"\"},{\"type\":\"jeepney\",\"name\":\"ROUTE 21: TAGBAK \\/ BUNTATALA TO FESTIVE WALK VIA SM CITY \\/ ATRIA\",\"link\":\"jeep21.php\",\"description\":\"\"},{\"type\":\"bus\",\"name\":\"ROUTE 10: BUNTATALA \\/ TAGBAK TERMINAL TO CITY PROPER LOOP\",\"link\":\"bus10.php\",\"description\":\"\"}]'),
